export interface ConnectorConfig {
  linearGraphqlUrl: string;
  linearApiKey: string;
  discordWebhookUrl: string;
  closedStateId: string;
  maxDigestLength?: number;
  linearWebhookSecret?: string;
}

export interface LinearWebhookPayload {
  action: string;
  type: string;
  createdAt: string;
  organizationId: string;
  webhookTimestamp: number;
  webhookId: string;
  url: string;
  actor: {
    id: string;
    type: string;
    name: string;
    email: string;
    url: string;
  };
  data: {
    id: string;
    updatedAt: string;
    number: number;
    title: string;
    priority: number;
    estimate: number;
    stateId: string;
    assigneeId: string;
    startedAt: string;
    completedAt: string | null;
    description?: string;
  };
  updatedFrom: {
    stateId: string;
    assigneeId: string;
    startedAt: string | null;
    updatedAt: string;
  };
}

export interface HandleResult {
  discordMessageId: string;
  discordChannelId: string;
  commentsFetched: number;
  truncated: boolean;
  skipped: boolean;
}

async function fetchAllComments(
  issueId: string,
  config: ConnectorConfig,
  fetch: typeof globalThis.fetch
): Promise<Array<{ author: string; content: string }>> {
  const comments: Array<{ author: string; content: string }> = [];
  let hasNextPage = true;
  let cursor: string | null = null;

  const query = `
    query GetComments($issueId: ID!, $after: String) {
      issue(id: $issueId) {
        comments(first: 100, after: $after) {
          edges {
            node {
              author { name }
              content
            }
          }
          pageInfo {
            hasNextPage
            endCursor
          }
        }
      }
    }
  `;

  while (hasNextPage) {
    const variables = { issueId, after: cursor };
    const response = await fetch(config.linearGraphqlUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${config.linearApiKey}`,
      },
      body: JSON.stringify({ query, variables }),
    });

    if (!response.ok) {
      const text = await response.text().catch(() => '');
      throw new Error(`Linear GraphQL API error: ${response.status} ${response.statusText} - ${text}`);
    }

    const result = (await response.json()) as {
      data?: {
        issue?: {
          comments?: {
            edges: Array<{ node: { author: { name: string }; content: string } }>;
            pageInfo: { hasNextPage: boolean; endCursor: string };
          };
        };
      };
      errors?: Array<{ message: string }>;
    };

    if (result.errors?.length) {
      throw new Error(`Linear GraphQL errors: ${result.errors.map(e => e.message).join(', ')}`);
    }

    const commentsData = result.data?.issue?.comments;
    if (!commentsData) {
      break;
    }

    for (const edge of commentsData.edges) {
      comments.push({
        author: edge.node.author.name,
        content: edge.node.content,
      });
    }

    hasNextPage = commentsData.pageInfo.hasNextPage;
    cursor = commentsData.pageInfo.endCursor;
  }

  return comments;
}

function buildDigest(payload: LinearWebhookPayload, comments: Array<{ author: string; content: string }>): string {
  const lines: string[] = [];
  lines.push(`Issue: ${payload.data.title}`);
  if (payload.data.description) {
    lines.push(`Description: ${payload.data.description}`);
  }
  if (comments.length > 0) {
    lines.push('Comments:');
    for (const comment of comments) {
      lines.push(`- ${comment.author}: ${comment.content}`);
    }
  }
  return lines.join('\n');
}

export async function handle(
  payload: LinearWebhookPayload,
  config: ConnectorConfig,
  fetch: typeof globalThis.fetch = globalThis.fetch
): Promise<HandleResult> {
  if (!payload.action) throw new Error('Missing required field: action');
  if (!payload.type) throw new Error('Missing required field: type');
  if (!payload.data) throw new Error('Missing required field: data');
  if (!payload.data.id) throw new Error('Missing required field: data.id');
  if (!payload.data.title) throw new Error('Missing required field: data.title');
  if (!payload.data.stateId) throw new Error('Missing required field: data.stateId');

  if (payload.action !== 'update' || payload.type !== 'Issue' || payload.data.stateId !== config.closedStateId) {
    return {
      discordMessageId: '',
      discordChannelId: '',
      commentsFetched: 0,
      truncated: false,
      skipped: true,
    };
  }

  const issueId = payload.data.id;

  let comments: Array<{ author: string; content: string }> = [];
  try {
    comments = await fetchAllComments(issueId, config, fetch);
  } catch (error) {
    console.log('[WARN] Failed to fetch comments for issue', issueId, error);
  }

  let digest = buildDigest(payload, comments);

  const maxLength = config.maxDigestLength ?? 2000;
  let truncated = false;
  if (digest.length > maxLength) {
    digest = digest.slice(0, maxLength - 3) + '...';
    truncated = true;
  }

  const discordResponse = await fetch(config.discordWebhookUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ content: digest }),
  });

  if (!discordResponse.ok) {
    const text = await discordResponse.text().catch(() => '');
    throw new Error(`Discord webhook error: ${discordResponse.status} ${discordResponse.statusText} - ${text}`);
  }

  const discordResult = (await discordResponse.json()) as {
    id: string;
    channel_id: string;
    content: string;
    timestamp: string;
  };

  return {
    discordMessageId: discordResult.id,
    discordChannelId: discordResult.channel_id,
    commentsFetched: comments.length,
    truncated,
    skipped: false,
  };
}

import { describe, it, expect, vi } from 'vitest';
import { handle, ConnectorConfig, LinearWebhookPayload } from './connector';
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse } from './fixtures';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      linearGraphqlUrl: 'https://api.linear.app/graphql',
      linearApiKey: 'test-linear-key',
      discordWebhookUrl: 'https://discord.com/api/webhooks/123/abc',
      closedStateId: 'f4e3d2c1-b0a9-8765-4321-0fed-cba98765',
      maxDigestLength: 2000,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as LinearWebhookPayload, config, fetch);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.skipped).toBe(false);
    expect(result.discordMessageId).toBe('123456789012345678');
    expect(result.discordChannelId).toBe('987654321098765432');
  });
});

describe('handle', () => {
  const baseConfig: ConnectorConfig = {
    linearGraphqlUrl: 'https://api.linear.app/graphql',
    linearApiKey: 'test-linear-key',
    discordWebhookUrl: 'https://discord.com/api/webhooks/123/abc',
    closedStateId: 'f4e3d2c1-b0a9-8765-4321-0fed-cba98765',
    maxDigestLength: 2000,
  };

  it('returns skipped when issue not closed', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ id: '1' }, 200));
    const payload = { ...SOURCE_EXAMPLE, data: { ...SOURCE_EXAMPLE.data, stateId: 'different-state' } };
    const result = await handle(payload as LinearWebhookPayload, baseConfig, fetch);
    expect(result.skipped).toBe(true);
    expect(calls.length).toBe(0);
  });

  it('throws on missing required field', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = { ...SOURCE_EXAMPLE, data: { ...SOURCE_EXAMPLE.data, id: undefined } } as any;
    await expect(handle(payload, baseConfig, fetch)).rejects.toThrow('Missing required field: data.id');
  });

  it('fetches comments with pagination and posts digest', async () => {
    let page = 0;
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        page++;
        if (page === 1) {
          return jsonResponse({
            data: {
              issue: {
                comments: {
                  edges: [
                    { node: { author: { name: 'Mike Johnson' }, content: 'Looks good!' } },
                    { node: { author: { name: 'Sarah Chen' }, content: 'Please add tests.' } },
                  ],
                  pageInfo: { hasNextPage: true, endCursor: 'cursor-1' },
                },
              },
            },
          });
        } else if (page === 2) {
          return jsonResponse({
            data: {
              issue: {
                comments: {
                  edges: [
                    { node: { author: { name: 'Alex Kim' }, content: 'Ship it!' } },
                  ],
                  pageInfo: { hasNextPage: false, endCursor: 'cursor-2' },
                },
              },
            },
          });
        }
        return jsonResponse({ errors: [{ message: 'Too many pages' }] }, 400);
      }
      if (req.url === 'https://discord.com/api/webhooks/123/abc') {
        return jsonResponse({
          id: 'msg-123',
          channel_id: 'chan-456',
          content: 'test',
          timestamp: new Date().toISOString(),
        }, 200);
      }
      return jsonResponse({ error: 'Not found' }, 404);
    });

    const result = await handle(SOURCE_EXAMPLE as unknown as LinearWebhookPayload, baseConfig, fetch);

    expect(result.skipped).toBe(false);
    expect(result.commentsFetched).toBe(3);
    expect(result.discordMessageId).toBe('msg-123');
    expect(result.discordChannelId).toBe('chan-456');

    const graphqlCalls = calls.filter(c => c.url === 'https://api.linear.app/graphql');
    expect(graphqlCalls.length).toBe(2);
    expect(graphqlCalls[0].json).toMatchObject({
      variables: { issueId: SOURCE_EXAMPLE.data.id, after: null },
    });
    expect(graphqlCalls[1].json).toMatchObject({
      variables: { issueId: SOURCE_EXAMPLE.data.id, after: 'cursor-1' },
    });

    const discordCall = calls.find(c => c.url === 'https://discord.com/api/webhooks/123/abc');
    expect(discordCall).toBeDefined();
    expect(discordCall!.json.content).toContain('Issue: Add user authentication to API endpoints');
    expect(discordCall!.json.content).toContain('Mike Johnson: Looks good!');
    expect(discordCall!.json.content).toContain('Sarah Chen: Please add tests.');
    expect(discordCall!.json.content).toContain('Alex Kim: Ship it!');
  });

  it('handles GraphQL fetch failure gracefully', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        throw new Error('Network error');
      }
      if (req.url === 'https://discord.com/api/webhooks/123/abc') {
        return jsonResponse({
          id: 'msg-123',
          channel_id: 'chan-456',
          content: 'test',
          timestamp: new Date().toISOString(),
        }, 200);
      }
      return jsonResponse({ error: 'Not found' }, 404);
    });

    const result = await handle(SOURCE_EXAMPLE as unknown as LinearWebhookPayload, baseConfig, fetch);

    expect(result.commentsFetched).toBe(0);
    expect(result.discordMessageId).toBe('msg-123');
    const discordCall = calls.find(c => c.url === 'https://discord.com/api/webhooks/123/abc');
    expect(discordCall).toBeDefined();
    expect(discordCall!.json.content).toContain('Issue: Add user authentication to API endpoints');
    expect(discordCall!.json.content).not.toContain('Comments:');
  });

  it('throws on Discord non-2xx response', async () => {
    const { fetch } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        return jsonResponse({
          data: { issue: { comments: { edges: [], pageInfo: { hasNextPage: false, endCursor: '' } } } },
        });
      }
      if (req.url === 'https://discord.com/api/webhooks/123/abc') {
        return jsonResponse({ error: 'Unauthorized' }, 401);
      }
      return jsonResponse({ error: 'Not found' }, 404);
    });

    await expect(handle(SOURCE_EXAMPLE as unknown as LinearWebhookPayload, baseConfig, fetch))
      .rejects.toThrow('Discord webhook error: 401 Unauthorized');
  });

  it('truncates long digest', async () => {
    const longComment = 'x'.repeat(3000);
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url === 'https://api.linear.app/graphql') {
        return jsonResponse({
          data: {
            issue: {
              comments: {
                edges: [{ node: { author: { name: 'Bot' }, content: longComment } }],
                pageInfo: { hasNextPage: false, endCursor: '' },
              },
            },
          },
        });
      }
      if (req.url === 'https://discord.com/api/webhooks/123/abc') {
        return jsonResponse({
          id: 'msg-123',
          channel_id: 'chan-456',
          content: 'test',
          timestamp: new Date().toISOString(),
        }, 200);
      }
      return jsonResponse({ error: 'Not found' }, 404);
    });

    const config = { ...baseConfig, maxDigestLength: 100 };
    const result = await handle(SOURCE_EXAMPLE as unknown as LinearWebhookPayload, config, fetch);

    expect(result.truncated).toBe(true);
    const discordCall = calls.find(c => c.url === 'https://discord.com/api/webhooks/123/abc');
    expect(discordCall!.json.content.length).toBeLessThanOrEqual(100);
    expect(discordCall!.json.content.slice(-3)).toBe('...');
  });
});

# Linear Issue Closed → Discord Digest Connector

This connector receives a Linear `issue.closed` webhook, fetches all comments on the issue via the Linear GraphQL API (with cursor pagination), formats a digest, and posts it to a Discord channel via a webhook.

## Configuration

The following environment variables are required:

| Variable | Description |
|----------|-------------|
| `LINEAR_WEBHOOK_SECRET` | Secret for verifying Linear webhook signatures (HMAC-SHA256). Used by the HTTP receiver before calling `handle()`. |
| `LINEAR_GRAPHQL_URL` | Linear GraphQL API endpoint (e.g., `https://api.linear.app/graphql`). |
| `LINEAR_API_KEY` | Bearer token for authenticating to the Linear GraphQL API. |
| `DISCORD_WEBHOOK_URL` | Full Discord webhook URL (format: `https://discord.com/api/webhooks/{webhook.id}/{webhook.token}`). |
| `LINEAR_CLOSED_STATE_ID` | The `stateId` value that represents the "closed" state in Linear. |

Optional:
| Variable | Description | Default |
|----------|-------------|---------|
| `MAX_DIGEST_LENGTH` | Maximum characters for the Discord message (Discord limit is 2000). | `2000` |

## Usage

```typescript
import { handle, ConnectorConfig } from './connector';

// In your webhook receiver (e.g., Express, Fastify, Cloudflare Worker):
app.post('/linear-webhook', async (req, res) => {
  // 1. Verify Linear signature (required)
  const signature = req.headers['linear-signature'];
  const timestamp = req.headers['linear-timestamp'];
  const rawBody = req.rawBody; // string
  // Verify HMAC-SHA256(rawBody, LINEAR_WEBHOOK_SECRET) === signature
  // Check timestamp freshness (replay protection)

  // 2. Parse JSON
  const payload = JSON.parse(rawBody);

  // 3. Call connector
  const config: ConnectorConfig = {
    linearGraphqlUrl: process.env.LINEAR_GRAPHQL_URL!,
    linearApiKey: process.env.LINEAR_API_KEY!,
    discordWebhookUrl: process.env.DISCORD_WEBHOOK_URL!,
    closedStateId: process.env.LINEAR_CLOSED_STATE_ID!,
    maxDigestLength: parseInt(process.env.MAX_DIGEST_LENGTH || '2000', 10),
    linearWebhookSecret: process.env.LINEAR_WEBHOOK_SECRET, // for reference
  };

  try {
    const result = await handle(payload, config);
    if (result.skipped) {
      return res.status(200).send('Issue not closed, skipped');
    }
    res.json({ success: true, messageId: result.discordMessageId });
  } catch (err) {
    console.error(err);
    res.status(500).send('Connector error');
  }
});
```

## Assumptions

- The Linear webhook payload includes `action: 'update'`, `type: 'Issue'`, and `data.stateId` matching the configured closed state ID when an issue is closed.
- Comments are not included in the webhook payload; they are fetched via the Linear GraphQL API using the issue ID from `data.id`.
- The Linear GraphQL API uses Relay-style cursor pagination (`hasNextPage`, `endCursor`) on a `comments` connection.
- The Discord webhook URL is pre-configured to target a specific channel; the connector posts a simple text message with `content`.
- The digest message format: issue title, description (if present), then each comment as `- Author: content`.
- If comment fetching fails (network error, API error), the connector logs a warning and posts the digest without comments rather than failing the entire webhook.
- Discord message content is truncated to `MAX_DIGEST_LENGTH` (default 2000) with `...` suffix if needed.
- The HTTP receiver is responsible for verifying the Linear webhook signature and timestamp before calling `handle()`.

