export interface DocumentedEndpoint {
  method: string
  /** As documented; may contain placeholders such as {id}, :id, <id> or a region host like usX. */
  url: string
  response: unknown
}

/** Target endpoints the connector may call, in the documented order, with their documented responses. */
export const TARGET_ENDPOINTS: DocumentedEndpoint[] = [
  {
    "method": "POST",
    "url": "https://discord.com/api/webhooks/{webhook.id}/{webhook.token}",
    "response": {
      "id": "123456789012345678",
      "channel_id": "987654321098765432",
      "content": "Issue: Add user authentication to API endpoints\n\nDescription: Implement JWT-based authentication...\n\nComments:\n- Mike Johnson: Looks good!\n- Sarah Chen: Please add tests.",
      "timestamp": "2025-01-24T16:45:22.384Z"
    }
  }
]

export interface RecordedCall {
  method: string
  url: string
  /** The request body exactly as sent (usually a JSON string). */
  body: string | undefined
  /** The body parsed as JSON, or undefined when it is not JSON. */
  json: unknown
  headers: Headers
}

/** The documented endpoint a request matches, placeholders and region subdomains included. */
export function findEndpoint(method: string, url: string): DocumentedEndpoint | undefined {
  return TARGET_ENDPOINTS.find((endpoint) => endpoint.method === method.toUpperCase() && urlMatches(endpoint.url, url))
}

/**
 * A fake fetch that answers every documented endpoint with its documented response and
 * rejects anything else. Use it in the contract test:
 *
 *   const { fetch, calls } = contractFetch()
 *   await handle(SOURCE_EXAMPLE as MyInput, { ...config, fetch })
 *   expect(calls.length).toBeGreaterThan(0)
 */
export function contractFetch(): { fetch: typeof fetch; calls: RecordedCall[] } {
  return fakeFetch((request) => {
    const endpoint = findEndpoint(request.method, request.url)
    if (!endpoint) throw new Error(`contract: ${request.method} ${request.url} is not a documented endpoint`)
    return jsonResponse(endpoint.response)
  })
}

/**
 * A correctly typed fake fetch for every other test. The handler receives the recorded
 * request: { method, url, body (string as sent), json (parsed body), headers (Headers) }.
 *
 *   const { fetch, calls } = fakeFetch((req) => req.url.endsWith('/deals') ? jsonResponse({ id: 1 }, 201) : jsonResponse({}, 404))
 */
export function fakeFetch(
  handler: (request: RecordedCall) => Response | Promise<Response>,
): { fetch: typeof fetch; calls: RecordedCall[] } {
  const calls: RecordedCall[] = []
  const fake = async (input: string | URL | Request, init: RequestInit = {}): Promise<Response> => {
    const url = input instanceof Request ? input.url : String(input)
    const method = (init.method ?? (input instanceof Request ? input.method : 'GET')).toUpperCase()
    const body = typeof init.body === 'string' ? init.body : init.body == null ? undefined : String(init.body)
    const call: RecordedCall = { method, url, body, json: parseJson(body), headers: new Headers(init.headers) }
    calls.push(call)
    return handler(call)
  }
  return { fetch: fake as typeof fetch, calls }
}

const STATUS_TEXT: Record<number, string> = {
  200: 'OK', 201: 'Created', 202: 'Accepted', 204: 'No Content',
  400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found', 409: 'Conflict',
  422: 'Unprocessable Entity', 429: 'Too Many Requests',
  500: 'Internal Server Error', 502: 'Bad Gateway', 503: 'Service Unavailable',
}

/** A JSON Response with the standard status text, e.g. jsonResponse({ error: 'nope' }, 401) -> "401 Unauthorized". */
export function jsonResponse(body: unknown, status = 200): Response {
  const init = { status, statusText: STATUS_TEXT[status] ?? '', headers: { 'Content-Type': 'application/json' } }
  return new Response(status === 204 ? null : JSON.stringify(body), init)
}

function parseJson(raw: string | undefined): unknown {
  if (raw === undefined) return undefined
  try {
    return JSON.parse(raw)
  } catch {
    return undefined
  }
}

function urlMatches(template: string, actual: string): boolean {
  const t = splitUrl(template)
  const a = splitUrl(actual)
  if (!t || !a) return false
  const tHost = t.host.split('.')
  const aHost = a.host.split('.')
  if (tHost.slice(-2).join('.') !== aHost.slice(-2).join('.')) return false
  const tPath = t.path.replace(/\/+$/, '').split('/')
  const aPath = a.path.replace(/\/+$/, '').split('/')
  if (tPath.length !== aPath.length) return false
  return tPath.every((segment, i) => isPlaceholder(segment) || segment === aPath[i])
}

function splitUrl(url: string): { host: string; path: string } | null {
  const match = url.match(/^https?:\/\/([^/?#]+)([^?#]*)/i)
  return match ? { host: (match[1] ?? '').toLowerCase(), path: match[2] || '/' } : null
}

function isPlaceholder(segment: string): boolean {
  return /^\{[^}]+\}$|^:[A-Za-z_]\w*$|^<[^>]+>$/.test(segment)
}

import { createHmac, timingSafeEqual } from 'crypto';

export interface ConnectorConfig {
  linearGraphqlUrl: string;
  linearApiKey: string;
  discordWebhookUrl: string;
  linearClosedStateId: string;
  maxDigestLength?: number;
  linearWebhookSecret?: string;
}

export interface LinearWebhookPayload {
  action: string;
  type: string;
  createdAt: string;
  organizationId: string;
  webhookTimestamp: number;
  webhookId: string;
  url: string;
  actor: {
    id: string;
    type: string;
    name: string;
    email: string;
    url: string;
  };
  data: {
    id: string;
    updatedAt: string;
    number: number;
    title: string;
    description: string | null;
    priority: number;
    estimate: number | null;
    stateId: string;
    assigneeId: string | null;
    startedAt: string | null;
    completedAt: string | null;
  };
  updatedFrom: {
    stateId: string;
    assigneeId: string | null;
    startedAt: string | null;
    updatedAt: string;
  };
}

export interface LinearComment {
  id: string;
  body: string;
  createdAt: string;
  user: {
    id: string;
    name: string;
    email: string;
  };
}

interface LinearCommentsResponse {
  data: {
    issue: {
      comments: {
        edges: Array<{ node: LinearComment }>;
        pageInfo: {
          hasNextPage: boolean;
          endCursor: string;
        };
      };
    };
  };
}

export interface ConnectorResult {
  success: boolean;
  skipped?: boolean;
  messageId?: string;
  error?: string;
}

const DEFAULT_MAX_DIGEST_LENGTH = 2000;
const LINEAR_GRAPHQL_QUERY = `
  query IssueComments($id: String!, $after: String) {
    issue(id: $id) {
      comments(after: $after, first: 100) {
        edges {
          node {
            id
            body
            createdAt
            user {
              id
              name
              email
            }
          }
        }
        pageInfo {
          hasNextPage
          endCursor
        }
      }
    }
  }
`;

async function fetchAllComments(
  config: ConnectorConfig,
  issueId: string
): Promise<LinearComment[]> {
  const allComments: LinearComment[] = [];
  let after: string | null = null;
  let hasNextPage = true;

  while (hasNextPage) {
    const response = await fetch(config.linearGraphqlUrl, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        Authorization: `Bearer ${config.linearApiKey}`,
      },
      body: JSON.stringify({
        query: LINEAR_GRAPHQL_QUERY,
        variables: { id: issueId, after },
      }),
    });

    if (!response.ok) {
      const errorText = await response.text().catch(() => response.statusText);
      throw new Error(`Linear GraphQL API error: ${response.status} ${errorText}`);
    }

    const data = (await response.json()) as LinearCommentsResponse;
    const edges = data.data?.issue?.comments?.edges ?? [];
    const pageInfo = data.data?.issue?.comments?.pageInfo;

    for (const edge of edges) {
      allComments.push(edge.node);
    }

    hasNextPage = pageInfo?.hasNextPage ?? false;
    after = pageInfo?.endCursor ?? null;
  }

  return allComments.sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime());
}

function formatDigest(
  issue: LinearWebhookPayload['data'],
  comments: LinearComment[],
  maxLength: number
): string {
  const lines: string[] = [];

  lines.push(`**${issue.title}**`);
  lines.push(`Linear Issue #${issue.number}: ${issue.url}`);

  if (issue.description) {
    lines.push('');
    lines.push(issue.description);
  }

  if (comments.length > 0) {
    lines.push('');
    lines.push('**Comments:**');
    for (const comment of comments) {
      lines.push(`- **${comment.user.name}**: ${comment.body}`);
    }
  }

  let content = lines.join('\n');

  if (content.length > maxLength) {
    content = content.slice(0, maxLength - 3) + '...';
  }

  return content;
}

async function postToDiscord(webhookUrl: string, content: string): Promise<string | null> {
  const response = await fetch(webhookUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ content }),
  });

  if (!response.ok) {
    const errorText = await response.text().catch(() => response.statusText);
    throw new Error(`Discord webhook error: ${response.status} ${errorText}`);
  }

  const data = (await response.json()) as { id?: string };
  return data.id ?? null;
}

export async function handle(
  payload: LinearWebhookPayload,
  config: ConnectorConfig
): Promise<ConnectorResult> {
  const maxDigestLength = config.maxDigestLength ?? DEFAULT_MAX_DIGEST_LENGTH;

  if (payload.action !== 'update' || payload.type !== 'Issue') {
    return { success: true, skipped: true };
  }

  const closedStateId = config.linearClosedStateId;
  const currentStateId = payload.data.stateId;
  const previousStateId = payload.updatedFrom.stateId;

  if (currentStateId !== closedStateId || previousStateId === closedStateId) {
    return { success: true, skipped: true };
  }

  let comments: LinearComment[] = [];
  let commentsFetchFailed = false;

  try {
    comments = await fetchAllComments(config, payload.data.id);
  } catch (error) {
    console.warn('Failed to fetch Linear comments:', error);
    commentsFetchFailed = true;
  }

  const content = formatDigest(payload.data, comments, maxDigestLength);

  try {
    const messageId = await postToDiscord(config.discordWebhookUrl, content);
    return { success: true, messageId: messageId ?? undefined };
  } catch (error) {
    console.error('Failed to post to Discord:', error);
    return { success: false, error: String(error) };
  }
}

export function verifyLinearSignature(
  secret: string,
  rawBody: string,
  signature: string,
  timestamp: string
): boolean {
  const expectedSignature = createHmac('sha256', secret, `${timestamp}.${rawBody}`);
  return timingSafeEqual(expectedSignature, signature);
}

export function isTimestampFresh(timestamp: string, toleranceMs = 300000): boolean {
  const now = Date.now();
  const then = parseInt(timestamp, 10) * 1000;
  return Math.abs(now - then) <= toleranceMs;
}

