  it('returns false for expired timestamp', async () => {
    const secret = 'test-secret';
    const payload = '{"test": "data"}';
    const timestamp = (Date.now() - 10 * 60 * 1000).toString(); // 10 minutes ago
    const key = await crypto.subtle.importKey(
      'raw',
      new TextEncoder().encode(secret),
      { name: 'HMAC', hash: 'SHA-256' },
      false,
      ['sign']
    );
    const sig = await crypto.subtle.sign('HMAC', key, new TextEncoder().encode(`${timestamp}.${payload}`));
    const signature = Array.from(new Uint8Array(sig)).map(b => b.toString(16).padStart(2, '0')).join('');

    const result = await verifyLinearSignature(secret, payload, signature, timestamp);
