function createFetchMock(responses: Map<string, { status: number; body: unknown }>) {
  const calls: Array<{ url: string; options: RequestInit }> = [];
  const fetchMock = vi.fn(async (url: string | URL | Request, options?: RequestInit) => {
    const urlStr = url instanceof Request ? url.url : url instanceof URL ? url.toString() : String(url);
    calls.push({ url: urlStr, options: options || {} });
    const key = urlStr;
    const response = responses.get(key) || { status: 404, body: { error: 'Not found' } };
    return {
      ok: response.status >= 200 && response.status < 300,
      status: response.status,
      statusText: '',
      json: async () => response.body,
      text: async () => JSON.stringify(response.body),
      headers: new Headers(),
    } as Response;
  });
  return { fetch: fetchMock, calls };
}

